#!/usr/bin/env node
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');
const PACKAGE='data/fag/litteratur/litteraturvitenskap_canonical_v1';
const read=f=>JSON.parse(fs.readFileSync(path.join(ROOT,f),'utf8'));
const write=(f,v)=>{const t=path.join(ROOT,f);fs.mkdirSync(path.dirname(t),{recursive:true});fs.writeFileSync(t,`${JSON.stringify(v,null,2)}\n`);};
const C=(id,term,definition,distinguish_from)=>({id,term,definition,distinguish_from});
const S=(id,title,coverageTopic,paragraphs,paragraphClaimIds,keyPoints)=>({id,title,coverageTopic,paragraphs,paragraphClaimIds,keyPoints});

const areas=[
 {id:'poetikk_estetikk_litteraritet',title:'Poetikk, estetikk og litteraritet',status:'chapter_and_overview_text_materialized',topics:['mimesis_representasjon','form_innhold','litteraritet_fiksjonalitet','estetisk_erfaring_dom','poetikkens_historie','kunst_autonomi_formal']},
 {id:'sprak_stil_retorikk',title:'Språk, stil og retorikk',status:'chapter_and_overview_text_materialized',topics:['diksjon_register_stemme','metafor_metonymi_bilde','ironi_paradoks_tvetydighet','retorisk_situasjon_appell','stilometri_stiltrekk','flerspraklighet_heteroglossia']}
];

const foundations=[
 {id:areas[0].id,title:areas[0].title,synthesis:'Poetikken undersøker prinsipper for litterær framstilling og form; estetikken undersøker erfaring, verdi og dom; litteraritet og fiksjonalitet avgrenser historiske praksiser, ikke tidløse essenser. Kapittelet følger begrepene fra antikkens mimesis og handlingslære gjennom autonomiestetikk og moderne formteori, med tydelige skiller mellom tekstegenskap, sjangerkonvensjon, leserhandling og verdidom.',topics:[
  ['mimesis_representasjon','Mimesis betegner ikke bare avbildning, men måter handling, tale og verden blir valgt og organisert i et verk. Platon og Aristoteles stiller ulike spørsmål om etterligningens kunnskap, følelser og samfunnsvirkning. Analysen må navngi medium, objekt og formprinsipp og unngå å måle all litteratur mot fotografisk likhet.',['mimesis','representasjon','sannsynlighet','handlingsmodell'],'Sofokles’ «Kong Oidipus» analysert gjennom Aristoteles’ skille mellom handlingskomposisjon, karakter, gjenkjennelse og omslag.'],
  ['form_innhold','Form og innhold er analytiske distinksjoner, ikke to deler som eksisterer uavhengig av hverandre. Ordrekkefølge, sjanger, medium og komposisjon bestemmer hva som kan framstilles, mens materiale og tematikk gir formen historisk motstand. En analyse bør vise hvilken omforming som skjer når samme hendelse fortelles med en annen stemme, rytme eller rekkefølge.',['form','materiale','komposisjon','forminnhold_relasjon'],'Virginia Woolfs «To the Lighthouse» undersøkt gjennom tidsdeling, perspektivskifte og hvordan tap blir formet uten direkte handlingsreferat.'],
  ['litteraritet_fiksjonalitet','Litteraritet viser til organiserte trekk og bruksmåter som gjør språk merkbart som litterært; fiksjonalitet viser til en kommunikativ praksis der oppdiktede utsagn inngår uten vanlig referensiell forpliktelse. Begrepene overlapper ikke fullstendig: sakprosa kan være litterær, og fiksjon kan opptre utenfor skjønnlitteraturen. Kontekst og sjangerpakt må derfor dokumenteres.',['litteraritet','fiksjonalitet','fiksjonell_talehandling','sjangerkonvensjon'],'Daniel Defoes «Robinson Crusoe» analysert gjennom historiske sannhetsmarkører, redaksjonell ramme og romanens tidlige fiksjonskonvensjoner.'],
  ['estetisk_erfaring_dom','Estetisk erfaring omfatter oppmerksomhet, følelse, forestilling og refleksjon i møte med form, men er ikke en universell reaksjon som teksten automatisk produserer. En estetisk dom framsetter et verdikrav som må begrunnes og historiseres. Tekstanalysen kan beskrive inviterte erfaringer; faktiske vurderinger krever resepsjons- eller leserdata.',['estetisk_erfaring','estetisk_dom','smak','forestillingsevne'],'Oscar Wildes «The Picture of Dorian Gray» undersøkt gjennom skjønnhet, moralsk vurdering og konflikt mellom forordets estetiske program og romanens form.'],
  ['poetikkens_historie','Poetikkens historie rommer normative lærebøker, sjangerteori, forfatterpoetikker og beskrivende vitenskapelige modeller. Aristoteles’ tragedieanalyse, arabisk resepsjon, renessansens regelpoetikker, romantisk organisisme og modernistiske manifester svarer på forskjellige institusjonelle spørsmål. En historisk framstilling må følge oversettelser, sjangre og bruk, ikke ordne alt som lineær framgang mot nåtiden.',['normativ_poetikk','deskriptiv_poetikk','forfatterpoetikk','resepsjonshistorie'],'Aristoteles’ «Poetikken» sammenholdt med dens arabiske og europeiske resepsjon som skiftende modeller av diktning og argument.'],
  ['kunst_autonomi_formal','Kunstautonomi betegner at estetiske verk og institusjoner utvikler egne normer og vurderingsformer, ikke at kunst er uten økonomi, politikk eller historie. Formålstjenlighet uten bestemt formål og formalisme gir ulike språk for selvstendig form. Analysen må undersøke både verkets interne organisasjon og de institusjonene som gjør autonomikravet mulig.',['autonomi','formaalstjenlighet','estetisk_institusjon','heteronomi'],'Charles Baudelaires «Les Fleurs du mal» analysert gjennom formell komposisjon, sensurprosessen i 1857 og spenningen mellom estetisk autonomi og juridisk regulering.']
 ].map(([id,text,concepts,example])=>({id,text,concepts,example}))},
 {id:areas[1].id,title:areas[1].title,synthesis:'Språk-, stil- og retorikkstudier undersøker hvordan ordvalg, syntaks, figurer, stemmer og sosiale register organiserer oppmerksomhet og handling. Kapittelet forbinder detaljert stilistikk med retorisk situasjon, metafor- og ironiteori, kvantitativ stilometri og Bakhtins heteroglossia. Hver slutning må skille tekstlig mønster, fortellerposisjon, historisk språkbruk og faktisk virkning på publikum.',topics:[
  ['diksjon_register_stemme','Diksjon er tekstens ordvalg i forhold til syntaks, sjanger og situasjon; register er sosialt gjenkjennelig språkbruk; stemme er en analytisk virkning av flere teksttrekk. Ingen av dem er direkte avtrykk av forfatterens personlighet. Analysen må identifisere kontraster, taleposisjon og historisk norm før den tilskriver klasse, autoritet eller intimitet.',['diksjon','register','stemme','sosiolekt'],'Jane Austens «Emma» analysert gjennom fri indirekte diskurs, høflighetsregister og skiftet mellom Emmas ordforråd og fortellerens korreksjon.'],
  ['metafor_metonymi_bilde','Metafor organiserer forståelse gjennom overføring og sammenstilling; metonymi forbinder uttrykk gjennom nærhet, del, årsak eller institusjon; litterære bilder kan aktivere begge. Figurer er ikke pynt som kan fjernes uten rest. Analysen må vise hvilke trekk som projiseres, hvilke som holdes tilbake, og hvordan bildet endres gjennom gjentakelse og kontekst.',['metafor','metonymi','billedfelt','konseptuell_profilering'],'Shakespeares sonett 73 undersøkt gjennom årstid, skumring og ild som skiftende modeller av alder, tid og kjærlighet.'],
  ['ironi_paradoks_tvetydighet','Ironi skaper avstand mellom ytring, posisjon og situasjon; paradoks organiserer tilsynelatende uforenlige påstander; tvetydighet holder flere betydningsmuligheter aktive. De kan ikke identifiseres bare fordi et utsagn er usant eller uklart. Analysen må dokumentere signaler, adressat, alternativ bokstavelig lesning og konsekvensen av å velge feil posisjon.',['ironi','paradoks','tvetydighet','ustabil_ironi'],'Jonathan Swifts «A Modest Proposal» analysert gjennom talerens økonomiske register, uholdbare bokstavelige forslag og den etiske risikoen ved satirisk distanse.'],
  ['retorisk_situasjon_appell','En retorisk situasjon forbinder et påtrengende problem, et publikum og begrensninger som ytringen forsøker å påvirke. Ethos, logos og pathos er samvirkende appellformer, ikke tre avsnitt som kan telles mekanisk. Litterære fortellere og figurer kan utføre retoriske handlinger, men faktisk overtalelse må undersøkes gjennom resepsjon.',['retorisk_situasjon','ethos','logos','pathos'],'Frederick Douglass’ «Narrative» analysert gjennom forord, vitneautoritet, dokumentasjon, adressat og abolisjonistisk publiseringssituasjon.'],
  ['stilometri_stiltrekk','Stilometri måler språklige mønstre som funksjonsord, ordlengde, syntaks eller sekvensfordeling på tvers av et dokumentert korpus. Metoden kan støtte attribusjon eller sammenligning, men resultatet avhenger av utgave, sjanger, normalisering og modellvalg. Et statistisk avvik er et funn som må fortolkes, ikke automatisk forfatterens signatur.',['stilometri','funksjonsord','trekksett','attribusjon'],'«The Federalist Papers» som klassisk attribusjonscase, sammenholdt med moderne krav til korpus, usikkerhet og validering.'],
  ['flerspraklighet_heteroglossia','Flerspråklighet omfatter språkvalg, oversettelse og veksling; heteroglossia beskriver sosialt differensierte stemmer og talemåter innenfor samme språkfelt. Romanen kan organisere slike språk uten å harmonisere dem. Analysen må identifisere hvem som rammer inn hvem, hvilke ord som forblir uoversatt, og hvordan makt fordeles mellom register og adressater.',['flerspraklighet','kodeveksling','heteroglossia','dobbeltstemt_diskurs'],'Toni Morrisons «Jazz» analysert gjennom muntlige register, fortellerkonkurranse, byspråk og musikalsk organisering uten å redusere romanen til jazz som løs metafor.']
 ].map(([id,text,concepts,example])=>({id,text,concepts,example}))}
];

