const toClaims=(rows,classification)=>rows.map(([id,claim,source_ids])=>({id,claim,source_ids,classification,status:'verified'}));

function materialize({area,foundation,sections,concepts,sources,claims,slugs,subtitle}){
 const dir=`${PACKAGE}/foundation_texts/${area.id}`,moduleFiles=slugs.map((slug,i)=>`${dir}/0${i+1}-${slug}.json`);
 for(let i=0;i<3;i++){const ss=sections.slice(i*2,i*2+2);write(moduleFiles[i],{schema:'history_go_literature_foundation_module_v1',qualityProfile:'full_depth_v2',id:`${area.id}-${i+1}`,title:slugs[i].split('-').map(x=>x[0].toUpperCase()+x.slice(1)).join(' '),sections:ss,workedExamples:ss.map(s=>({title:`Prøv modellen: ${s.title.replace(/^\d+\.\s*/,'')}`,object:foundation.topics.find(t=>t.id===s.coverageTopic).example,steps:['Identifiser tekstversjon, medium, analyseenhet og historisk norm.','Registrer minst tre teksttrekk før teoribegrepene anvendes.','Prøv hovedhypotesen mot en alternativ formal, retorisk eller historisk forklaring.','Formuler hva som krever resepsjonsdata eller andre kilder utover teksten.'],claimIds:s.paragraphClaimIds.flat().slice(0,3)})),commonMisconceptions:[{claim:'Teoribegrepet kan erstatte analysen av tekststedet.',correction:'Begrepet skal operasjonaliseres gjennom lokaliserbare trekk, mellomledd, alternativer og inferensgrense.'},{claim:'Et tekstlig virkemiddel beviser hvordan alle lesere faktisk reagerer.',correction:'Teksten kan organisere en mulig erfaring eller appell; faktisk respons krever resepsjons- eller empiriske data.'}]});}
 const conceptFile=`${dir}/concepts.json`,claimsFile=`${dir}/claims.json`,wrapper=`${PACKAGE}/foundation_texts/${area.id}.json`;
 write(conceptFile,{schema:'history_go_literature_concept_registry_v1',version:'1.0.0',subject_id:'litteratur',coverage_area_id:area.id,status:'canonical_full_depth_concepts',concepts});
 write(claimsFile,{schema:'history_go_fagverk_claims_v1',version:'1.0.0',subject_id:'litteratur',chapter_id:area.id,verified_at:'2026-08-07',verification_status:'verified',sources,claims});
 write(wrapper,{schema:'history_go_literature_foundation_chapter_v1',version:'1.0.0',qualityProfile:'full_depth_v2',subject:'litteratur',id:area.id,title:area.title,subtitle,lead:foundation.synthesis,coverage_topics:area.topics,learningObjectives:['skille sentrale begreper og deres teorihistoriske bruk','analysere navngitte verk gjennom lokaliserbare teksttrekk','skille tekstegenskap, konvensjon og faktisk leservirkning','prøve konkurrerende formelle og historiske forklaringer','koble fagpåstander til presise kilder','formulere analyseobjektets inferensgrense'],moduleFiles,conceptRegistry:conceptFile,claimsFile,editorial_status:'foundation_text_ready',completion_note:'Alle seks kontraktstemaer er materialisert som full-dybdeartikler med begreper, navngitte verk, alternative forklaringer og påstandsspor.'});return wrapper;
}

const wrappers=[
 materialize({area:areas[0],foundation:foundations[0],sections:poeticsSections,concepts:poeticsConcepts,sources:poeticsSources,claims:toClaims(poeticsClaimRows,'poetikk_estetikk'),slugs:['mimesis-og-form','fiksjon-og-erfaring','poetikk-og-autonomi'],subtitle:'Framstilling, form, erfaring og kunstens historiske normer'}),
 materialize({area:areas[1],foundation:foundations[1],sections:styleSections,concepts:styleConcepts,sources:styleSources,claims:toClaims(styleClaimRows,'stilistikk_retorikk'),slugs:['diksjon-og-bilder','ironi-og-appell','stilometri-og-flerspraklighet'],subtitle:'Fra ordvalg og billedfelt til appell, måling og sosiale stemmer'})
];

const coverageFile=`${PACKAGE}/coverage_contract_v1.json`,coverage=read(coverageFile);coverage.coverage_areas=coverage.coverage_areas.map(row=>areas.find(a=>a.id===row.id)||row);const complete=coverage.coverage_areas.filter(row=>row.status==='chapter_and_overview_text_materialized');coverage.progress={areas_total:coverage.coverage_areas.length,areas_with_foundation_text:coverage.coverage_areas.length,areas_complete:complete.length,topics_total:coverage.completion_definition.required_topic_count,topics_with_foundation_text:coverage.completion_definition.required_topic_count,topics_complete:complete.flatMap(row=>row.topics).length,honest_status:'Alle 28 områder og 168 temaer har særskrevet oversiktstekst. Åtte områder og 48 temaer har full kapitteldybde, definerte begreper, navngitte analyseobjekter og påstandsspor; 20 områder og 120 temaer trenger fortsatt tilsvarende full-dybde-materialisering.'};write(coverageFile,coverage);
const topicsFile=`${PACKAGE}/topic_foundations_v1.json`,topics=read(topicsFile);const replacements=new Map(foundations.map(row=>[row.id,row]));topics.areas=topics.areas.map(row=>replacements.get(row.id)||row);write(topicsFile,topics);
const indexFile=`${PACKAGE}/index.json`,index=read(indexFile);index.files.foundation_chapters=[...new Set([...index.files.foundation_chapters,...wrappers.map(f=>f.replace(`${PACKAGE}/`,''))])];let mc=0,cc=0,sc=0,qc=0;for(const f of index.files.foundation_chapters){const ch=read(`${PACKAGE}/${f}`),cr=read(ch.conceptRegistry),cl=read(ch.claimsFile);mc+=ch.moduleFiles.length;cc+=cr.concepts.length;sc+=cl.sources.length;qc+=cl.claims.length;}index.summary={coverage_area_count:coverage.coverage_areas.length,required_topic_count:coverage.completion_definition.required_topic_count,area_synthesis_count:topics.areas.length,topic_foundation_text_count:topics.areas.flatMap(row=>row.topics).length,materialized_foundation_chapter_count:index.files.foundation_chapters.length,materialized_module_count:mc,defined_concept_count:cc,verified_source_count:sc,verified_claim_count:qc,completion_status:'poetics_style_core_expanded_20_areas_pending_full_depth'};write(indexFile,index);
